// Generates MoonBit tests from the fixed execution-account configuration and
// Checkpoint Resolution signature corpora. Expected values are taken only from
// the corpora (computed independently of product code); nothing is derived
// from product output. `--write` regenerates; the default mode fails when a
// generated file is stale.
import assert from 'node:assert/strict';
import {readFileSync, writeFileSync} from 'node:fs';

const read = path => JSON.parse(readFileSync(path, 'utf8'));
const literal = text => '"' + [...text].map(c => {
  const cp = c.codePointAt(0);
  return cp < 32 || cp > 126 ? '\\u{' + cp.toString(16) + '}' :
    c === '"' || c === '\\' ? '\\' + c : c;
}).join('') + '"';
const reversed = value => Array.isArray(value) ? value.map(reversed) :
  value !== null && typeof value === 'object' ?
    Object.fromEntries(Object.entries(value).reverse()
      .map(([key, item]) => [key, reversed(item)])) : value;
const outputs = [];

// actql-execution-account-config/0.1 (Run#account-config).
{
  const corpus = read('portability/corpus/execution-account-config.json');
  assert.equal(corpus.version, 'actql-execution-account-config-vectors/0.1');
  const lines = [
    '// Generated by scripts/check-execution-authorization-vectors.mjs --write. Do not edit.',
    '// Expected identities and outcomes come from portability/corpus/execution-account-config.json.',
  ];
  for (const c of corpus.cases) {
    lines.push('', '///|', `test ${literal('account config identity: ' + c.id)} {`,
      `  assert_eq(account_configuration_cid_json(${literal(JSON.stringify(c.config))}), Ok(${literal(c.expected_cid)}))`,
      '  // Object member order is not part of the canonical spelling.',
      `  assert_eq(account_configuration_cid_json(${literal(JSON.stringify(reversed(c.config)))}), Ok(${literal(c.expected_cid)}))`,
      '}');
  }
  const base = corpus.cases[0].config;
  for (const r of corpus.rejections) {
    const v = structuredClone(base);
    if (r.remove) delete v[r.remove];
    Object.assign(v, r.changes ?? {});
    if (r.entries) v.entries = r.entries;
    lines.push('', '///|', `test ${literal('account config rejects: ' + r.id)} {`,
      `  assert_true(admit_account_configuration_json(${literal(JSON.stringify(v))}) is Err(_))`,
      '}');
  }
  for (const c of corpus.overlap) {
    const expected = c.expected === 'conflict' ? 'Err(ConflictingOutcomes(_))' : 'Ok(_)';
    assert.ok(['conflict', 'valid'].includes(c.expected), c.id);
    lines.push('', '///|', `test ${literal('account config overlap: ' + c.id)} {`,
      `  assert_true(admit_account_configuration_json(${literal(JSON.stringify(c.config))}) is ${expected})`,
      '}');
  }
  const {config, cases} = corpus.evaluation;
  lines.push('', '///|', 'test "account config evaluation vectors" {',
    `  let config = admit_account_configuration_json(${literal(JSON.stringify(config))}).unwrap()`);
  for (const c of cases) {
    const t = c.tuple;
    const tuple = `{ principal: ${literal(t.principal)}, connection: ${literal(t.connection)}, resource: ${literal(t.resource)}, operation: ${literal(t.operation)} }`;
    const outcome = `evaluate_account(config, ${tuple})`;
    const e = c.expected;
    lines.push(`  // ${c.id}`);
    if (e.outcome === 'allow') lines.push(`  assert_true(${outcome} is Allow(${literal(e.entry_id)}))`);
    else if (e.outcome === 'deny') lines.push(`  assert_true(${outcome} is Deny(Explicit(${literal(e.entry_id)})))`);
    else if (e.outcome === 'no_match') lines.push(`  assert_true(${outcome} is Deny(NoMatch))`);
    else {
      assert.equal(e.outcome, 'delegate', c.id);
      lines.push(`  guard ${outcome} is Delegate(found) else { fail(${literal(c.id)}) }`,
        `  assert_eq(found.entry_id, ${literal(e.entry_id)})`);
    }
  }
  lines.push('}');
  outputs.push(['src/execution_authorization/corpus.generated_test.mbt', lines.join('\n') + '\n',
    `${corpus.cases.length} identity, ${corpus.rejections.length} rejection, ` +
    `${corpus.overlap.length} overlap and ${cases.length} evaluation account-config vectors`]);
}

// Checkpoint Resolution signature preimages (Run#resolution-admission).
{
  const corpus = read('portability/corpus/checkpoint-resolution-signatures.json');
  assert.equal(corpus.version, 'actql-checkpoint-resolution-signature-vectors/0.1');
  const lines = [
    '// Generated by scripts/check-execution-authorization-vectors.mjs --write. Do not edit.',
    '// Expected preimages come from portability/corpus/checkpoint-resolution-signatures.json.',
    '// Ed25519 verification of the signatures is a Host port concern (Node test).',
    '',
    '///|',
    'fn signature_vector_limits() -> WireLimits {',
    '  { max_wire_bytes: 65536, max_nodes: 4096, max_depth: 32 }',
    '}',
  ];
  for (const c of corpus.cases) {
    const preimage = c.kind === 'checkpoint_resolution' ? 'resolution_proof_preimage' :
      'verified_resolution_attestation_preimage';
    assert.ok(['checkpoint_resolution', 'verified_checkpoint_resolution'].includes(c.kind), c.id);
    lines.push('', '///|', `test ${literal('resolution signature preimage: ' + c.id)} {`,
      `  assert_eq(${preimage}(${literal(JSON.stringify(c.artifact))}, signature_vector_limits()), Ok(${literal(c.expected_unsigned_cid)}))`,
      `  assert_eq(${preimage}(${literal(JSON.stringify(reversed(c.artifact)))}, signature_vector_limits()), Ok(${literal(c.expected_unsigned_cid)}))`,
      '  // The self CID includes the signature, so it is never the preimage.',
      `  assert_true(${literal(c.expected_self_cid)} != ${literal(c.expected_unsigned_cid)})`,
      '}');
  }
  outputs.push(['src/checkpoint_runtime/signature_vectors.generated_test.mbt', lines.join('\n') + '\n',
    `${corpus.cases.length} Resolution signature-preimage vectors`]);
}

for (const [path, text, summary] of outputs) {
  if (process.argv.includes('--write')) writeFileSync(path, text);
  else assert.equal(readFileSync(path, 'utf8'), text, `stale ${path}`);
  console.log(`${path}: ${summary}.`);
}
